import traceback

class CapituloInexistenteError(Exception):
    pass

CAPITULOS = {"Rut": 4, "Jonás": 4}

def validar(libro, capitulo):
    if not 1 <= capitulo <= CAPITULOS[libro]:
        raise CapituloInexistenteError(f"{libro} no tiene capítulo {capitulo}")
    return f"{libro} {capitulo}"

def probar_validar():
    assert validar("Rut", 1) == "Rut 1"
    assert validar("Jonás", 4) == "Jonás 4"      # caso borde: el último
    try:
        validar("Rut", 5)
    except CapituloInexistenteError:
        pass
    else:
        assert False, "validar debía fallar con Rut 5"

probar_validar()
print("Pruebas: todo bien")

try:
    validar("Abdías", 1)
except KeyError:
    print(traceback.format_exc())

