import traceback

class ChapterNotFoundError(Exception):
    pass

CHAPTERS = {"Ruth": 4, "Jonah": 4}

def validate(book, chapter):
    if not 1 <= chapter <= CHAPTERS[book]:
        raise ChapterNotFoundError(f"{book} has no chapter {chapter}")
    return f"{book} {chapter}"

def test_validate():
    assert validate("Ruth", 1) == "Ruth 1"
    assert validate("Jonah", 4) == "Jonah 4"      # edge case: the last one
    try:
        validate("Ruth", 5)
    except ChapterNotFoundError:
        pass
    else:
        assert False, "validate should have failed with Ruth 5"

test_validate()
print("Tests: all good")

try:
    validate("Obadiah", 1)
except KeyError:
    print(traceback.format_exc())

