def buscar(lista, objetivo):
    """Posición de objetivo en una lista ordenada, o -1 si no está (búsqueda binaria)."""
    inicio, fin = 0, len(lista) - 1
    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == objetivo:
            return medio
        elif lista[medio] < objetivo:
            inicio = medio + 1
        else:
            fin = medio - 1
    return -1

def probar_buscar():
    libros = ["Abdías", "Hageo", "Joel", "Jonás", "Rut"]
    for i, libro in enumerate(libros):
        assert buscar(libros, libro) == i
    assert buscar(libros, "Amós") == -1
    assert buscar(libros, "Aarón") == -1
    assert buscar(libros, "Zacarías") == -1
